        if stripped.startswith("[") and stripped.endswith("]"):
            current = sections.setdefault(stripped[1:-1].strip(), {})
            continue
        cut = min((i for i in (stripped.find("="), stripped.find(":")) if i >= 0), default=-1)
        if cut < 0:
            raise ParseError(lineno, f"unrecognized line: {stripped!r}")
        if current is None:
            raise ParseError(lineno, "key before any section")
        key = stripped[:cut].strip().lower()
        if not key:
            raise ParseError(lineno, "empty key")
        current[key] = stripped[cut + 1:].strip()
        last_key = key

    resolved: dict[tuple[str, str], str] = {}
    resolving: set[tuple[str, str]] = set()

    def resolve(section: str, key: str) -> str:
        ref = (section, key)
        if ref in resolved:
            return resolved[ref]
        if section not in sections:
            raise InterpolationError(f"no section {section!r}")
        if key not in sections[section]:
            raise InterpolationError(f"no key {key!r} in section {section!r}")
        if ref in resolving:
            raise InterpolationError(f"cycle at {section}:{key}")
        resolving.add(ref)
        value = sections[section][key]
        out = []
        i = 0
        while i < len(value):
            if value.startswith("$$", i):
                out.append("$")
                i += 2
            elif value.startswith("${", i) and "}" in value[i + 2:]:
                end = value.index("}", i + 2)
                name = value[i + 2:end]
                ref_section, sep, ref_key = name.rpartition(":")
                if not sep:
                    ref_section = section
                out.append(resolve(ref_section.strip(), ref_key.strip().lower()))
                i = end + 1
            else:
                out.append(value[i])
                i += 1
        resolving.discard(ref)
        resolved[ref] = "".join(out)
        return resolved[ref]

    return {
        name: {key: resolve(name, key) for key in keys}
        for name, keys in sections.items()
    }
'''
